-- Legal drafts: closure of the 15.11.2026 review (owner approved). DRAFTS ONLY: status stays 'draft', nothing is
-- published, no acceptance is created. Each edit must match exactly once, otherwise the whole migration stops.
-- * General terms replaced by the reviewed text (v1.1 content; first publication keeps version number 1).
--   The operator sentence is carried over verbatim from the current draft.
-- * Founders period: one wording everywhere — six months from the store's first successful connection.
-- * Orderly close of collaborations after an unaccepted increase: 14 calendar days' notice.
-- * Late orders: attributed by the time they were placed (implemented in 20261115100200).
-- * Disconnection: orders not yet received are not imported automatically.
-- * Cookies: exact WooCommerce behaviour (30 days, consent API or the store's choice).
-- * Privacy: Google Fonts removed (fonts are served by LINKUP itself).

create or replace function pg_temp.legal_edit(p_key text, p_locale text, p_pattern text, p_new text) returns void language plpgsql as $$
declare v_old text;
begin
  if not exists (select 1 from public.legal_documents) then return; end if;   -- empty database (local tests)
  select body into v_old from public.legal_documents where doc_key = p_key and locale = p_locale and status = 'draft';
  if v_old is null then raise exception 'draft not found: % %', p_key, p_locale; end if;
  if (select count(*) from regexp_matches(v_old, p_pattern, 'g')) <> 1 then raise exception 'pattern must match once: % % %', p_key, p_locale, left(p_pattern, 40); end if;
  update public.legal_documents set body = regexp_replace(v_old, p_pattern, p_new) where doc_key = p_key and locale = p_locale and status = 'draft';
end $$;

-- Replaces a whole draft body; {OPERATOR} is filled with the operator sentence taken from the current draft.
create or replace function pg_temp.legal_set(p_key text, p_locale text, p_op_pattern text, p_body text) returns void language plpgsql as $$
declare v_old text; v_op text;
begin
  if not exists (select 1 from public.legal_documents) then return; end if;
  select body into v_old from public.legal_documents where doc_key = p_key and locale = p_locale and status = 'draft';
  if v_old is null then raise exception 'draft not found: % %', p_key, p_locale; end if;
  v_op := substring(v_old from p_op_pattern);
  if v_op is null then raise exception 'operator sentence not found: % %', p_key, p_locale; end if;
  update public.legal_documents set body = replace(p_body, '{OPERATOR}', v_op) where doc_key = p_key and locale = p_locale and status = 'draft';
end $$;

