/* ---------- Cookies and sales attribution ---------- */
select pg_temp.legal_edit('cookies', 'he', '\n2\. ב-WooCommerce[^\n]*',
  E'\n2. ב-WooCommerce הייחוס מתבצע באמצעות תוסף LINKUP. כשמבקר מגיע דרך קישור של משפיען, התוסף שומר באתר החנות עוגייה בשם linkup_ref, המכילה קוד משפיען ושעת ביקור בלבד, ל-30 יום. אם באתר החנות פועל באנר עוגיות התומך ב-WP Consent API, העוגייה נשמרת רק לאחר שהמבקר הסכים לעוגיות שיווק. אם אין באנר כזה, החנות בוחרת אם לשמור את העוגייה ולציין זאת בהודעת העוגיות שלה, או שלא לשמור אותה כלל; האחריות לבחירה זו ולעמידה בדין החל עליה היא של החנות. ב-Shopify אפליקציית LINKUP מפעילה פיקסל ייחוס דרך הממשק הרשמי של Shopify; Shopify טוענת אותו רק כאשר הלקוח הסכים לעוגיות שיווק וניתוח, ובאזורים שבהם נדרשת הסכמה הוא לא פועל ללא הסכמה.');
select pg_temp.legal_edit('cookies', 'he', 'נשמרים בדפדפן הלקוח עד 90 יום\.', 'נשמרים בדפדפן הלקוח עד 90 יום ב-Shopify ועד 30 יום ב-WooCommerce.');
select pg_temp.legal_edit('cookies', 'he', 'כאשר הלקוח דוחה עוגיות, חוסם סקריפטים או מוחק אותם,',
  'כאשר הלקוח דוחה עוגיות, חוסם סקריפטים או מוחק אותם, או כאשר החנות בחרה שלא לשמור עוגייה ללא הסכמה,');
select pg_temp.legal_edit('cookies', 'en', '\n2\. On WooCommerce[^\n]*',
  E'\n2. On WooCommerce, attribution works through the LINKUP plugin. When a visitor arrives through a creator link, the plugin sets a first-party cookie named linkup_ref on the store, holding only the creator code and visit time, for 30 days. If the store runs a cookie banner that supports the WP Consent API, the cookie is set only after the visitor accepts marketing cookies. Without such a banner, the store chooses whether to set the cookie and mention it in its cookie notice, or never to set it; the store is responsible for that choice and for the law that applies to it. On Shopify, the LINKUP app turns on an attribution pixel through Shopify''s official interface; Shopify loads it only when the customer consented to marketing and analytics cookies, and where consent is required it does not run without it.');
select pg_temp.legal_edit('cookies', 'en', 'visit data is kept in the customer''s browser for up to 90 days\.',
  'visit data is kept in the customer''s browser for up to 90 days on Shopify and up to 30 days on WooCommerce.');
select pg_temp.legal_edit('cookies', 'en', 'when a customer declines, blocks or deletes cookies or scripts,',
  'when a customer declines, blocks or deletes cookies or scripts, or when the merchant chose not to set a cookie without consent,');

